R.append((7161543,
("Dhansak de cordero", "Un curry de picante medio hecho con cordero, verduras y lentejas en una salsa espesa y rica, llena de sabor.", "4", "421 g",
 ["2 cucharaditas de aceite de canola", "1 cebolla, picada", "350 g de pierna de cordero, en cubos", "2 zanahorias, picadas", "4 dientes de ajo, machacados", "3 cm de raíz de jengibre fresco, rallada", "100 g de lentejas rojas", "1 cubito de caldo de cordero o de pollo bajo en sal en 400 ml de agua hirviendo", "1 lata de 400 g de tomates picados", "1 cucharada de pasta de curry suave", "1 a 2 camotes (400 g), pelados y picados", "1 berenjena, picada", "20 g de cilantro fresco, picado en trozos grandes"],
 ["Agregue el aceite a una olla, añada la cebolla y cocine de 3 a 4 minutos, hasta que empiece a dorarse.", "Agregue el cordero y cocine otros 4 a 5 minutos, hasta que esté bien dorado. Agregue las zanahorias, el ajo y el jengibre y cocine otros 2 a 3 minutos, revolviendo con frecuencia.", "Agregue las lentejas, el caldo, los tomates y la pasta de curry y mezcle bien. Deje que hierva, tape, baje el fuego y cocine a fuego lento 1 hora.", "Agregue el camote y la berenjena, mezcle y tape de nuevo. Cocine a fuego lento otros 20 minutos.", "Compruebe que el cordero esté suave. Si no lo está, cocine a fuego lento otros 10 a 15 minutos. Incorpore el cilantro fresco, guardando un poco para decorar, y sirva."],
 ["Puede preparar este platillo con cualquier carne magra, como res o cerdo.", "Para una versión rápida, use cubos de pollo o de pavo y cocine a fuego lento 15 minutos en lugar de 1 hora, antes de agregar el camote y la berenjena.", "Instrucciones para congelar: Se puede congelar una vez cocinado. Descongele en el refrigerador o en el microondas y recaliente hasta que esté muy caliente por completo.", "Porciones de fruta/verdura por porción: 4"], []),
("دانساك لحم الضأن", "كاري متوسط الحرارة مصنوع من لحم الضأن والخضار والعدس في صلصة غنية وثخينة مليئة بالنكهة.", "4", "421 غ",
 ["2 ملعقة صغيرة زيت اللفت (الكانولا)", "1 حبة بصل، مفرومة", "350 غ لحم فخذ ضأن مقطع مكعبات", "2 حبة جزر، مفرومة", "4 فصوص ثوم، مهروسة", "3 سم جذر زنجبيل طازج، مبشور", "100 غ عدس أحمر", "1 مكعب مرق ضأن أو دجاج قليل الملح في 400 مل ماء مغلي", "1 علبة 400 غ طماطم مقطعة", "1 ملعقة كبيرة معجون كاري خفيف", "1-2 حبة بطاطا حلوة (400 غ)، مقشّرة ومقطعة", "1 حبة باذنجان، مقطعة", "20 غ كزبرة خضراء طازجة، مفرومة خشنًا"],
 ["ضع الزيت في قدر، ثم أضف البصل واطبخه من 3 إلى 4 دقائق حتى يبدأ لونه بالاحمرار.", "أضف لحم الضأن واطبخ من 4 إلى 5 دقائق أخرى حتى يحمرّ جيدًا. أضف الجزر والثوم والزنجبيل واطبخ من 2 إلى 3 دقائق أخرى مع التحريك باستمرار.", "أضف العدس والمرق والطماطم ومعجون الكاري وامزج جيدًا. اتركه حتى يغلي، ثم ضع الغطاء، واخفض الحرارة، واتركه على نار هادئة ساعة واحدة.", "أضف البطاطا الحلوة والباذنجان وامزج وغطِّ القدر مرة أخرى. اتركه على نار هادئة 20 دقيقة أخرى.", "تأكد من أن لحم الضأن طري. وإن لم يكن كذلك فاتركه على نار هادئة 10 إلى 15 دقيقة أخرى. أضف الكزبرة الطازجة مع الاحتفاظ بقليل منها للتزيين، وقدّمه."],
 ["يمكنك تحضير هذا الطبق بأي لحم قليل الدهن، مثل لحم البقر أو الخنزير.", "للحصول على نسخة سريعة، استخدم مكعبات الدجاج أو الديك الرومي واتركها على نار هادئة 15 دقيقة بدلًا من ساعة واحدة، قبل إضافة البطاطا الحلوة والباذنجان.", "تعليمات التجميد: يمكن تجميده بعد الطهي. أذبه في الثلاجة أو الميكروويف وأعد تسخينه حتى يصبح ساخنًا تمامًا من الداخل.", "حصص الفاكهة/الخضار في الحصة الواحدة: 4"], [])))
R.append((7161660,
("Coles de Bruselas y hash con huevo pochado", "Un platillo satisfactorio, ideal para una cena familiar o un desayuno sustancioso.", "4", "362 g",
 ["200 g de papas", "300 g de camotes", "500 g de coles de Bruselas, recortadas", "1 pizca grande de pimienta blanca", "2 cucharaditas de aceite de oliva", "1 cebolla grande, picada finamente", "4 huevos, pochados"],
 ["Friegue las papas y los camotes y quíteles cualquier mancha, pero no los pele. Córtelos en trozos grandes y cúbralos con agua hirviendo. Cocine a fuego lento de 10 a 12 minutos.", "Agregue las coles de Bruselas y vuelva a poner la tapa. Cocine de 7 a 10 minutos, hasta que estén cocidas pero todavía bastante firmes. Escurra todo el líquido.", "Agregue la pimienta y machaque de manera rústica para mezclar todo, dejando algunos trozos de col en el puré. Reserve.", "Agregue el aceite de oliva a otra sartén grande antiadherente a fuego medio y luego añada la cebolla. Cocine de 3 a 4 minutos, revolviendo con frecuencia.", "Ahora agregue a la sartén la mezcla de papa y coles y mezcle bien. Aplane para que cubra toda la sartén. Cocine 5 minutos, volteando con frecuencia para revolver la mezcla, y repita un par de veces para asegurarse de que se forme una costra crujiente.", "Coloque un huevo pochado encima y sirva."],
 ["Es perfecto para aprovechar sobras; si tiene papas o coles frías, simplemente caliéntelas unos minutos y comience desde el paso 3.", "Otras verduras, como zanahorias, nabo sueco o chirivías, también funcionan bien.", "Los grupos «de riesgo», como bebés, niños, mujeres embarazadas, adultos mayores y personas enfermas, deben evitar los huevos crudos o poco cocidos, a menos que puedan garantizar que se producen bajo el programa de garantía de calidad Lion Code.", "Porciones de fruta/verdura por porción: 2"], []),
("كرنب بروكسل والهاش مع بيض مسلوق بلا قشر", "طبق مشبع مثالي لوجبة عشاء عائلية أو فطور دسم.", "4", "362 غ",
 ["200 غ بطاطس", "300 غ بطاطا حلوة", "500 غ كرنب بروكسل، منظّف", "رشة كبيرة من الفلفل الأبيض", "2 ملعقة صغيرة زيت زيتون", "1 حبة بصل كبيرة، مفرومة ناعمًا", "4 بيضات، مسلوقة بلا قشر (بوشيه)"],
 ["افرك البطاطس والبطاطا الحلوة وأزل أي عيوب عنها، لكن لا تقشّرها. قطّعها إلى قطع كبيرة وغطّها بالماء المغلي. اتركها على نار هادئة من 10 إلى 12 دقيقة.", "أضف كرنب بروكسل وأعد الغطاء. اطبخ من 7 إلى 10 دقائق حتى ينضج مع بقائه متماسكًا إلى حد ما. صفِّ كل السائل.", "أضف الفلفل واهرسها هرسًا خشنًا لمزج كل شيء معًا، مع ترك بعض قطع الكرنب في الهريس. ضعها جانبًا.", "ضع زيت الزيتون في مقلاة كبيرة غير لاصقة أخرى على نار متوسطة، ثم أضف البصل. اطبخه من 3 إلى 4 دقائق مع التحريك باستمرار.", "الآن أضف خليط البطاطس والكرنب إلى المقلاة وامزج جيدًا. سوِّه بحيث يغطي المقلاة بالكامل. اطبخه 5 دقائق مع تقليبه باستمرار لخلط الخليط، وكرّر ذلك مرتين لضمان تكوّن قشرة مقرمشة.", "ضع بيضة مسلوقة بلا قشر في الأعلى وقدّمه."],
 ["هذا الطبق مثالي لاستهلاك البقايا، فإذا كان لديك بطاطس أو كرنب بارد فسخّنه بضع دقائق وابدأ من الخطوة 3.", "تناسب خضار أخرى أيضًا مثل الجزر واللفت السويدي والجزر الأبيض (الباستناك).", "يجب أن تتجنب الفئات «المعرّضة للخطر» مثل الرضع والأطفال والحوامل وكبار السن والمرضى البيض النيئ أو غير المطهو جيدًا، إلا إذا كان بالإمكان ضمان إنتاجه بموجب برنامج ضمان الجودة «Lion Code».", "حصص الفاكهة/الخضار في الحصة الواحدة: 2"], [])))
R.append((7163244,
("Taza para microondas: quiche sin masa de elote y Cheddar", "Una botana sabrosa llena de sabor salado pero baja en sal: ideal para una cena instantánea o una merienda rápida para los niños.", "1", "172 g",
 ["1 huevo, batido", "2 cucharadas de yogur estilo griego 0 % grasa", "1 cucharadita colmada de fécula de maíz", "15 g de queso Cheddar semidescremado, rallado finamente", "2 cebollitas de cambray, picadas finamente", "40 g de elote (maíz) congelado, descongelado", "una buena molida de pimienta negra", "media cucharadita de aceite de canola"],
 ["Ponga el huevo en un tazón y bata con el yogur, la fécula de maíz y el queso. Incorpore la cebollita y el elote. Agregue una molida de pimienta.", "Engrase ligeramente una taza y agregue los ingredientes. Caliente dos minutos a máxima potencia (800 W). Deje reposar 1 minuto antes de servir."],
 ["Se puede comer directamente de la taza o desmoldar en un plato y servir con ensalada o verduras de temporada.", "Los chícharos congelados quedan bien en lugar del elote, o pruebe con una mezcla de ambos.", "Agregue un poco de albahaca fresca, cebollín, cilantro o perejil para dar más sabor.", "Porciones de fruta/verdura por porción: 0"], []),
("كوب الميكروويف: كيش بالذرة الحلوة والشيدر بدون عجينة", "وجبة خفيفة لذيذة مليئة بالنكهة المالحة ولكنها قليلة الملح، مثالية لعشاء فوري أو وجبة سريعة للأطفال.", "1", "172 غ",
 ["1 بيضة، مخفوقة", "2 ملعقة كبيرة زبادي على الطريقة اليونانية خالٍ من الدسم (0%)", "1 ملعقة صغيرة مكوّمة نشا الذرة", "15 غ جبن شيدر نصف دسم، مبشور ناعمًا", "2 حبة بصل أخضر، مفرومة ناعمًا", "40 غ ذرة حلوة مجمدة، مذابة", "رشة كبيرة من الفلفل الأسود المطحون", "نصف ملعقة صغيرة زيت اللفت (الكانولا)"],
 ["ضع البيضة في وعاء واخفقها مع الزبادي ونشا الذرة والجبن. أضف البصل الأخضر والذرة وحرّك. أضف رشة فلفل.", "ادهن كوبًا بقليل من الزيت وضع فيه المكونات. سخّنه دقيقتين على أعلى قدرة (800 واط). اتركه دقيقة واحدة قبل التقديم."],
 ["يمكن تناوله مباشرة من الكوب أو قلبه على طبق وتقديمه مع السلطة أو الخضار الموسمية.", "تنجح البازلاء المجمدة بدلًا من الذرة، أو جرّب مزيجًا من الاثنين.", "أضف قليلًا من الريحان الطازج أو الثوم المعمر أو الكزبرة أو البقدونس لنكهة إضافية.", "حصص الفاكهة/الخضار في الحصة الواحدة: 0"], [])))
R.append((7165971,
("Bullabesa", "Una sustanciosa sopa mediterránea de mariscos, llena de verduras y ajo. Una comida completa en un tazón.", "4", "500 g",
 ["1 camote, pelado y en cubos (200 g)", "1 zanahoria, en cubitos pequeños (100 g)", "1 cubito de caldo de pescado, disuelto en 600 ml de agua", "medio bulbo de hinojo, en rebanadas (175 g)", "1 pimiento amarillo, en rebanadas (140 g)", "1 puerro, picado (150 g)", "1 pizca diminuta de cúrcuma (para dar color; más económica que el azafrán tradicional)", "1 buena pizca de pimienta blanca", "2 dientes de ajo, machacados", "2 cucharaditas de aceite de girasol", "4 filetes de besugo (90 g cada uno), cortados por la mitad para obtener 8 piezas", "1 paquete de 150 g de camarones jumbo cocidos y pelados", "1 paquete de 150 g de carne de mejillón cocida y refrigerada", "2 tomates grandes, pelados, sin semillas y picados en trozos pequeños (100 g de pulpa)", "1 cucharada de perejil picado finamente", "una buena molida de pimienta negra"],
 ["Ponga el camote y la zanahoria en una olla con el caldo, deje que hierva, luego baje el fuego, tape y cocine a fuego lento 7 minutos.", "Agregue el hinojo, el pimiento amarillo, el puerro, la cúrcuma, la pimienta blanca y el ajo, mezcle, tape y cocine a fuego lento otros 5 minutos.", "Mientras tanto, ponga 1 cucharadita de aceite en una sartén grande antiadherente a fuego medio-alto. Cuando la sartén esté caliente, agregue 4 piezas de pescado, con la piel hacia abajo, y cocine de 2 a 3 minutos. Voltéelas y cocine otros 1 a 2 minutos. Colóquelas en un plato caliente y cocine los demás filetes con otra cucharadita de aceite; si tiene una sartén lo bastante grande, puede hacerlo todo de una vez.", "Agregue los mejillones y los camarones a las verduras y al caldo, deje que hierva y cocine 2 minutos.", "Reparta las verduras, los camarones, los mejillones y el caldo entre 4 tazones. Coloque los filetes de pescado encima, espolvoree con perejil, pulpa de tomate picada y una pizca de pimienta negra, y sirva."],
 ["La bullabesa se preparaba tradicionalmente con restos de pescado, lo que hubiera de temporada, así que prácticamente cualquier pescado sirve.", "Para pelar los tomates, sumérjalos en agua hirviendo 1 minuto y la piel se quitará fácilmente.", "Porciones de fruta/verdura por porción: 2"], []),
("بويابيس", "حساء مأكولات بحرية متوسطي دسم، مليء بالخضار والثوم. وجبة مشبعة في وعاء.", "4", "500 غ",
 ["1 حبة بطاطا حلوة، مقشّرة ومقطعة مكعبات (200 غ)", "1 حبة جزر، مقطعة مكعبات صغيرة (100 غ)", "1 مكعب مرق سمك، مذاب في 600 مل ماء", "نصف بصلة شمر، مقطعة شرائح (175 غ)", "1 حبة فلفل رومي أصفر، مقطعة شرائح (140 غ)", "1 حبة كراث، مفرومة (150 غ)", "رشة صغيرة جدًا من الكركم (للون، وأرخص من الزعفران التقليدي)", "رشة كبيرة من الفلفل الأبيض", "2 فص ثوم، مهروسة", "2 ملعقة صغيرة زيت دوار الشمس", "4 قطع فيليه سمك الدنيس (90 غ لكل قطعة)، مقطعة إلى نصفين للحصول على 8 قطع", "1 عبوة 150 غ جمبري ملكي مطهو ومقشّر", "1 عبوة 150 غ لحم بلح البحر مطهو ومبرّد", "2 حبة طماطم كبيرة، مقشّرة ومنزوعة البذور ومفرومة قطعًا صغيرة (100 غ لب)", "1 ملعقة كبيرة بقدونس مفروم ناعمًا", "رشة كبيرة من الفلفل الأسود المطحون"],
 ["ضع البطاطا الحلوة والجزر في قدر مع المرق، واتركه حتى يغلي، ثم اخفض الحرارة وغطِّ القدر واتركه على نار هادئة 7 دقائق.", "أضف الشمر والفلفل الرومي الأصفر والكراث والكركم والفلفل الأبيض والثوم وامزج، ثم غطِّ القدر واتركه على نار هادئة 5 دقائق أخرى.", "في هذه الأثناء، ضع ملعقة صغيرة واحدة من الزيت في مقلاة كبيرة غير لاصقة على نار متوسطة إلى عالية. عندما تسخن المقلاة، أضف 4 قطع من السمك، مع جعل جهة الجلد لأسفل، واطبخها من 2 إلى 3 دقائق. اقلبها واطبخها من دقيقة إلى دقيقتين أخريين. ضعها على طبق ساخن واطبخ باقي شرائح السمك مع ملعقة صغيرة أخرى من الزيت، وإذا كانت مقلاتك كبيرة بما يكفي فيمكنك طهيها دفعة واحدة.", "أضف بلح البحر والجمبري إلى الخضار والمرق، واتركها حتى تغلي ثم اطبخها دقيقتين.", "وزّع الخضار والجمبري وبلح البحر والمرق على 4 أوعية. ضع شرائح السمك فوقها، ورشّ البقدونس ولب الطماطم المفروم ورشة من الفلفل الأسود وقدّمها."],
 ["كان البويابيس يُحضَّر تقليديًا من بقايا السمك، أي ما يتوفر في الموسم، لذا يصلح تقريبًا أي نوع من السمك.", "لتقشير الطماطم، اغمسها في ماء يغلي دقيقة واحدة وستنزع القشرة بسهولة.", "حصص الفاكهة/الخضار في الحصة الواحدة: 2"], [])))
R.append((7176015,
("Sopa de col rizada y lentejas verdes", "Una sopa nutritiva, rápida de preparar y muy saludable.", "4", "362 g",
 ["2 cucharaditas de aceite de girasol", "2 cebollas, picadas finamente", "1 zanahoria grande, en cubitos", "1 tallo de apio, picado", "1 a 2 dientes de ajo, machacados", "1 cucharadita de comino molido", "1 cucharada de puré de tomate", "1 lata de 400 g de lentejas verdes en agua (agregue también el agua)", "200 g de cavolo nero (col rizada negra) o col rizada, picada (sin los tallos gruesos)", "500 ml de caldo de verduras", "pimienta negra, al gusto"],
 ["Ponga el aceite en una olla a fuego medio, agregue las cebollas y revuelva de 7 a 10 minutos, hasta que estén bien doradas.", "Agregue la zanahoria y el apio y cocine otros 2 a 3 minutos, revolviendo con frecuencia.", "Ahora agregue el ajo, el comino, el puré de tomate y las lentejas, y mezcle bien.", "Agregue el caldo, deje que hierva, baje el fuego, tape y cocine a fuego lento 12 minutos.", "Agregue la col rizada, vuelva a poner la tapa y cocine a fuego lento otros 5 minutos; sazone con pimienta y sirva."],
 ["Puede usar cualquier caldo, como de pollo o de res. El caldo puede tener mucha sal, así que elija opciones reducidas en sal siempre que sea posible.", "Pruebe agregar una pechuga de pollo deshebrada o trozos de tofu marinado o ahumado.", "También puede agregar otras verduras, como pimientos, calabacitas, brócoli o elote enlatado.", "Instrucciones para congelar: Congele en porciones y luego descongele en el refrigerador, o en el microondas, cuidando de revolver con frecuencia.", "Porciones de fruta/verdura por porción: 3"], []),
("حساء الكرنب الأجعد والعدس الأخضر", "حساء مغذٍّ سريع التحضير وصحي للغاية.", "4", "362 غ",
 ["2 ملعقة صغيرة زيت دوار الشمس", "2 حبة بصل، مفرومة ناعمًا", "1 حبة جزر كبيرة، مقطعة مكعبات", "1 ساق كرفس، مفرومة", "1-2 فص ثوم، مهروسة", "1 ملعقة صغيرة كمون مطحون", "1 ملعقة كبيرة معجون طماطم", "1 علبة 400 غ عدس أخضر في الماء (أضف الماء أيضًا)", "200 غ كرنب كالي الأسود (كافولو نيرو) أو الكرنب الأجعد، مفروم (بعد إزالة السيقان السميكة)", "500 مل مرق خضار", "فلفل أسود، حسب الذوق"],
 ["ضع الزيت في قدر على نار متوسطة، وأضف البصل وحرّكه من 7 إلى 10 دقائق حتى يحمرّ جيدًا.", "أضف الجزر والكرفس واطبخ من 2 إلى 3 دقائق أخرى مع التحريك باستمرار.", "الآن أضف الثوم والكمون ومعجون الطماطم والعدس وامزج جيدًا.", "أضف المرق واتركه حتى يغلي، ثم اخفض الحرارة وغطِّ القدر واتركه على نار هادئة 12 دقيقة.", "أضف الكرنب وأعد الغطاء واتركه على نار هادئة 5 دقائق أخرى، ثم تبّله بالفلفل وقدّمه."],
 ["يمكنك استخدام أي مرق مثل مرق الدجاج أو اللحم. وقد يكون المرق عالي الملح، لذا اختر الأنواع قليلة الملح كلما أمكن.", "جرّب إضافة صدر دجاج مقطع خيوطًا أو قطع توفو متبّل أو مدخّن.", "يمكنك أيضًا إضافة خضار أخرى مثل الفلفل الرومي أو الكوسا أو البروكلي أو الذرة الحلوة المعلبة.", "تعليمات التجميد: جمّده في حصص ثم أذبه في الثلاجة، أو أذبه في الميكروويف مع الحرص على التحريك باستمرار.", "حصص الفاكهة/الخضار في الحصة الواحدة: 3"], [])))
R.append((7176104,
("Fool de ruibarbo", "Un postre de ruibarbo cocido, endulzado con edulcorante artificial e incorporado a yogur bajo en grasa y crème fraîche.", "6", "117 g",
 ["400 g de ruibarbo, cortado en trozos de 1 cm", "edulcorante artificial, al gusto (equivalente a 8 cucharaditas de azúcar, como 8 tabletas de stevia, machacadas)", "150 g de yogur griego 0 % grasa", "100 g de crème fraîche reducida en grasa"],
 ["Ponga el ruibarbo en una olla con 3 cucharadas de agua. Deje que hierva, baje el fuego, tape y cocine a fuego lento 6 minutos, revolviendo con frecuencia y agregando otra cucharada de agua si empieza a pegarse. El ruibarbo debe quedar suave, pero conservar su forma.", "Pase el ruibarbo a un tazón y agregue el edulcorante artificial, si lo usa. Mezcle bien y pruebe, agregando un poco más de edulcorante artificial si es necesario; luego deje enfriar. Recuerde que la fruta contiene azúcares naturales, así que no endulce de más.", "En un tazón, mezcle el yogur y la crème fraîche e incorpore el ruibarbo con movimientos envolventes. Reparta en copas y refrigere antes de servir."],
 ["Se puede preparar con anticipación y conservar en el refrigerador unas horas. O, si desea prepararlo el día anterior, refrigere el ruibarbo por separado y mézclelo con el yogur y la crème fraîche cuando lo necesite.", "Esta receta funciona bien con otras frutas ácidas, como grosellas espinosas o grosellas rojas.", "Puede usar casi cualquier fruta, aunque no necesitará endulzarla tanto si la fruta es dulce. Pruebe con albaricoques, duraznos, nectarinas, frambuesas o cerezas.", "Esta receta usa yogur 0 % grasa y crème fraîche reducida en grasa, pero puede usar una versión natural de su elección. Sin embargo, esto cambiará la información nutricional y la textura del platillo.", "Para una versión vegana, use yogur de soya o de coco sin azúcar."], []),
("فول الراوند (حلوى الراوند بالزبادي)", "حلوى من الراوند المطهو، محلّى بمحلّي صناعي ومطوي مع الزبادي قليل الدسم والكريمة الفرنسية (كريم فريش).", "6", "117 غ",
 ["400 غ راوند، مقطع قطعًا بطول 1 سم", "محلّي صناعي، حسب الرغبة (ما يعادل 8 ملاعق صغيرة سكر، مثل 8 أقراص ستيفيا مسحوقة)", "150 غ زبادي يوناني خالٍ من الدسم (0%)", "100 غ كريمة فرنسية (كريم فريش) قليلة الدسم"],
 ["ضع الراوند في قدر مع 3 ملاعق كبيرة من الماء. اتركه حتى يغلي، ثم اخفض الحرارة، وضع الغطاء واتركه على نار هادئة 6 دقائق مع التحريك باستمرار، وأضف ملعقة كبيرة أخرى من الماء إذا بدأ يلتصق. يجب أن يكون الراوند طريًا ولكنه محتفظ بشكله.", "انقل الراوند إلى وعاء وأضف المحلّي الصناعي إن استخدمته. امزج جيدًا وتذوّقه، وأضف قليلًا من المحلّي الصناعي إن لزم الأمر، ثم اتركه ليبرد. تذكّر أن الفاكهة تحتوي على سكريات طبيعية، فلا تفرط في التحلية.", "في وعاء، اخلط الزبادي والكريمة الفرنسية معًا ثم اطوِ الراوند فيهما. ضعه في كؤوس وبرّده قبل التقديم."],
 ["يمكن تحضيره مسبقًا وحفظه في الثلاجة لبضع ساعات. أو إذا أردت تحضيره قبل يوم من التقديم، فبرّد الراوند بشكل منفصل واخلطه مع الزبادي والكريمة الفرنسية عند الحاجة.", "تنجح هذه الوصفة مع فواكه حامضة أخرى مثل الكشمش الشوكي أو الكشمش الأحمر.", "يمكنك استخدام معظم الفواكه، مع أنك لن تحتاج إلى التحلية بالقدر نفسه إذا كانت الفاكهة حلوة. جرّب المشمش أو الخوخ أو النكتارين أو توت العليق أو الكرز.", "تستخدم هذه الوصفة زبادي خاليًا من الدسم (0%) وكريمة فرنسية قليلة الدسم، ولكن يمكنك استخدام نسخة سادة من اختيارك. غير أن ذلك سيغيّر المعلومات الغذائية وقوام الطبق.", "للحصول على نسخة نباتية، استخدم زبادي الصويا أو جوز الهند غير المحلّى."], [])))
build(8, R)
